// sb-patches.cpp — Validated patch transactions, embedded WAV assets, randomizer and routes.
#include "sb-plugin.h"
using namespace juce;
String PrismProcessor::title()const{const ScopedLock lock(metadata);return patchTitle;}
String PrismProcessor::macroTitle(int n)const{const ScopedLock lock(metadata);return macroTitles[n];}
void PrismProcessor::nameMacro(int n,const String& value){if(n<0||n>=8)return;const ScopedLock lock(metadata);macroTitles.set(n,value.substring(0,20));}
var PrismProcessor::patch()const{
 auto object=std::make_unique<DynamicObject>();object->setProperty("format","dualsynth-patch");object->setProperty("version",1);object->setProperty("engine","B");
 {const ScopedLock lock(metadata);object->setProperty("name",patchTitle);object->setProperty("category",category);Array<var> labels,tagList;for(const auto& name:macroTitles)labels.add(name);for(const auto& tag:tags)tagList.add(tag);object->setProperty("macros",labels);object->setProperty("tags",tagList);}
 auto* values=new DynamicObject;const auto& schema=SynthB::Schema::get();for(size_t i=0;i<schema.specs.size();++i)values->setProperty(Identifier(String(schema.specs[i].key)),double(read(int(i))));object->setProperty("params",var(values));
 Array<var> mods;for(int n=0;n<SynthB::routes;++n){int base=schema.loc.route[n],src=int(read(base+SynthB::source)),dest=int(read(base+SynthB::destination))-1;if(src==0||dest<0)continue;auto* route=new DynamicObject;route->setProperty("src",String(SynthB::sourceNames()[size_t(src)]));route->setProperty("dst",String(schema.specs[size_t(dest)].key));route->setProperty("amount",read(base+SynthB::depth));route->setProperty("bipolar",read(base+SynthB::bipolar)>.5f);route->setProperty("curve",read(base+SynthB::shape));mods.add(var(route));}object->setProperty("mod",mods);
 std::array<int,10> rack{};for(int i=0;i<10;++i)rack[size_t(i)]=int(read(schema.loc.order[i]));rack=SynthB::resolvedRack(rack);Array<var> effects;for(int n=0;n<10;++n){int module=rack[size_t(n)],base=schema.loc.fx[module];auto* fx=new DynamicObject;fx->setProperty("type",String(SynthB::effectNames()[size_t(module)]));fx->setProperty("on",read(base)>.5f);auto* params=new DynamicObject;for(int k=1;k<SynthB::fxSize;++k){auto& spec=schema.specs[size_t(base+k)];params->setProperty(Identifier(String(spec.key).fromLastOccurrenceOf(".",false,false)),double(read(base+k)));}fx->setProperty("params",var(params));effects.add(var(fx));}object->setProperty("fx",effects);
 auto* mapping=new DynamicObject;for(int cc=0;cc<128;++cc){int index=ccAssignments[size_t(cc)].load();if(index>=0)mapping->setProperty(String(cc),String(schema.specs[size_t(index)].key));}object->setProperty("midi",var(mapping));
 if(const auto* asset=currentWave.load(std::memory_order_acquire)){auto* wave=new DynamicObject;wave->setProperty("name",asset->name);wave->setProperty("frames",asset->frames);wave->setProperty("encoding","float32-le-base64");wave->setProperty("data",Base64::toBase64(asset->raw.data(),asset->raw.size()*sizeof(float)));object->setProperty("wavetable",var(wave));}
 return var(object.release());
}
Result PrismProcessor::restore(const var& incoming,bool commit, std::function<void()> beforePublish){
 if(!incoming.isObject()||incoming["format"].toString()!="dualsynth-patch"||incoming["engine"].toString()!="B"||int(incoming["version"])!=1)return Result::fail("Choose a version 1 Synth B patch.");
 auto* properties=incoming["params"].getDynamicObject();if(!properties)return Result::fail("Missing parameter object.");const auto& schema=SynthB::Schema::get();auto state=schema.initial();
 for(const auto& entry:properties->getProperties()){int index=schema.find(entry.name.toString().toStdString());if(index<0)return Result::fail("Unknown parameter: "+entry.name.toString());const auto& spec=schema.specs[size_t(index)];float value=0;
  if(entry.value.isString()&&!spec.options.empty()){int choice=-1;for(size_t n=0;n<spec.options.size();++n)if(String(spec.options[n]).equalsIgnoreCase(entry.value.toString()))choice=int(n);if(choice<0)return Result::fail("Unknown selection: "+entry.value.toString());value=float(choice);}
  else {if(!entry.value.isDouble()&&!entry.value.isInt()&&!entry.value.isInt64()&&!entry.value.isBool())return Result::fail("A parameter is not numeric.");value=float(entry.value);}
  if(!std::isfinite(value)||value<spec.low||value>spec.high)return Result::fail("Parameter outside its range: "+entry.name.toString());state[size_t(index)]=spec.valid(value);
 }
 if(!properties->hasProperty("mod1.source"))if(auto* rows=incoming["mod"].getArray()){
  if(rows->size()>SynthB::routes)return Result::fail("Too many modulation routes.");for(int n=0;n<rows->size();++n){const auto& row=rows->getReference(n);String source=row["src"].toString().removeCharacters(" ").toLowerCase();int src=-1;for(size_t i=0;i<SynthB::sourceNames().size();++i)if(String(SynthB::sourceNames()[i]).removeCharacters(" ").toLowerCase()==source)src=int(i);int dst=schema.find(row["dst"].toString().toStdString());float depth=float(row["amount"]);if(src<0||dst<0||!std::isfinite(depth)||std::abs(depth)>1)return Result::fail("Invalid modulation route.");int base=schema.loc.route[n];state[size_t(base)]=float(src);state[size_t(base+1)]=float(dst+1);state[size_t(base+2)]=depth;if(row.hasProperty("bipolar"))state[size_t(base+3)]=bool(row["bipolar"])?1.f:0.f;if(row.hasProperty("curve")){float curve=float(row["curve"]);if(!std::isfinite(curve)||curve<.25f||curve>4)return Result::fail("Invalid modulation curve.");state[size_t(base+4)]=curve;}}
 }
 // Descriptive FX imports are accepted when canonical parameter entries are absent.
 if(auto* effects=incoming["fx"].getArray()){
  if(effects->size()>10)return Result::fail("Too many rack entries.");std::array<bool,10> seen{};
  for(int slot=0;slot<effects->size();++slot){const auto& fx=effects->getReference(slot);int module=-1;for(int n=0;n<10;++n)if(String(SynthB::effectNames()[size_t(n)]).equalsIgnoreCase(fx["type"].toString()))module=n;
   if(module<0||seen[size_t(module)])return Result::fail("Invalid or duplicate effect type.");seen[size_t(module)]=true;int base=schema.loc.fx[module];String prefix="fx"+String(module+1)+".";
   if(!properties->hasProperty(Identifier(String(schema.specs[size_t(schema.loc.order[slot])].key))))state[size_t(schema.loc.order[slot])]=float(module);
   if(fx.hasProperty("on")&&!properties->hasProperty(Identifier(prefix+"on")))state[size_t(base)]=bool(fx["on"])?1.f:0.f;
   if(auto* values=fx["params"].getDynamicObject())for(const auto& entry:values->getProperties()){String key=prefix+entry.name.toString();int index=schema.find(key.toStdString());if(index<base||index>=base+SynthB::fxSize)return Result::fail("Unknown effect parameter: "+key);if(properties->hasProperty(Identifier(key)))continue;const auto& spec=schema.specs[size_t(index)];if(!entry.value.isDouble()&&!entry.value.isInt()&&!entry.value.isInt64()&&!entry.value.isBool())return Result::fail("Effect parameter must be numeric.");float value=float(entry.value);if(!std::isfinite(value)||value<spec.low||value>spec.high)return Result::fail("Effect parameter outside its range.");state[size_t(index)]=spec.valid(value);}
  }
 }
 std::array<int,128> mappings;mappings.fill(-1);if(auto* map=incoming["midi"].getDynamicObject())for(const auto& entry:map->getProperties()){String name=entry.name.toString();int cc=name.getIntValue(),parameter=schema.find(entry.value.toString().toStdString());if(name!=String(cc)||cc<0||cc>127||parameter<0)return Result::fail("Invalid MIDI mapping.");mappings[size_t(cc)]=parameter;}
 const Imported* asset=nullptr;std::unique_ptr<Imported> pending;
 if(incoming.hasProperty("wavetable")){const var wave=incoming["wavetable"];int frames=int(wave["frames"]);String encoded=wave["data"].toString();if(frames<1||frames>64||encoded.length()>800000||wave["encoding"].toString()!="float32-le-base64")return Result::fail("Invalid embedded wavetable.");MemoryOutputStream stream;if(!Base64::convertFromBase64(stream,encoded)||stream.getDataSize()!=size_t(frames*2048)*sizeof(float))return Result::fail("Damaged wavetable data.");
  pending=std::make_unique<Imported>();pending->frames=frames;pending->name=wave["name"].toString().substring(0,80);pending->raw.resize(size_t(frames*2048));std::memcpy(pending->raw.data(),stream.getData(),stream.getDataSize());for(float x:pending->raw)if(!std::isfinite(x)||std::abs(x)>16)return Result::fail("Unsafe wavetable samples.");
  {const ScopedLock lock(metadata);for(const auto& existing:waveAssets)if(existing->frames==frames&&existing->name==pending->name&&existing->raw==pending->raw){asset=existing.get();break;}if(!asset&&waveAssets.size()>=32)return Result::fail("This instance retains 32 imported tables for audio safety. Reopen the instance before importing more.");}
  if(!asset){pending->table=SynthB::WaveSet::fromFrames(pending->raw,frames,pending->name.toStdString());asset=pending.get();}
 }
 if((int(state[size_t(schema.loc.osc[0])])==30||int(state[size_t(schema.loc.osc[1])])==30)&&!asset)return Result::fail("This patch requires an embedded wavetable.");
 if(!commit)return Result::ok(); // validation only: nothing above touched any state
 if (beforePublish) beforePublish();
 silence.store(true);undo.beginNewTransaction("Recall patch");for(size_t i=0;i<schema.specs.size();++i){auto* param=parameters.getParameter(schema.specs[i].key);param->setValueNotifyingHost(param->convertTo0to1(state[i]));}for(int cc=0;cc<128;++cc)ccAssignments[size_t(cc)].store(mappings[size_t(cc)]);
 {const ScopedLock lock(metadata);if(pending&&asset==pending.get())waveAssets.push_back(std::move(pending));currentWave.store(asset,std::memory_order_release);patchTitle=incoming["name"].toString().substring(0,80);category=incoming["category"].toString();tags.clear();if(auto* list=incoming["tags"].getArray())for(const auto& tag:*list)tags.add(tag.toString().substring(0,40));if(auto* names=incoming["macros"].getArray())for(int i=0;i<std::min(8,names->size());++i)macroTitles.set(i,names->getReference(i).toString().substring(0,20));}
 return Result::ok();
}
void PrismProcessor::selectFactory(int n){if(n>=0&&n<factory.size())restore(factory[n]);}
Result PrismProcessor::open(const File& file){if(file.getSize()>2*1024*1024)return Result::fail("Patch exceeds 2 MB.");var data;auto result=JSON::parse(file.loadFileAsString(),data);return result.failed()?result:restore(data);}
Result PrismProcessor::save(const File& file){auto data=patch();data.getDynamicObject()->setProperty("name",file.getFileNameWithoutExtension());if(!file.replaceWithText(JSON::toString(data,true)))return Result::fail("Could not write patch.");const ScopedLock lock(metadata);patchTitle=file.getFileNameWithoutExtension();return Result::ok();}
void PrismProcessor::getStateInformation(MemoryBlock& block){auto json=JSON::toString(patch(),true);block.replaceAll(json.toRawUTF8(),size_t(json.getNumBytesAsUTF8()));}
void PrismProcessor::setStateInformation(const void* bytes,int length){if(length<=0||length>2*1024*1024)return;var json;if(JSON::parse(String::fromUTF8(static_cast<const char*>(bytes),length),json).wasOk())restore(json);}
Result PrismProcessor::importWave(const File& file,int oscillator,int cycleLength){
 AudioFormatManager manager;manager.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(manager.createReaderFor(file));if(!reader||reader->lengthInSamples<32||reader->lengthInSamples>48000*60)return Result::fail("Choose a WAV with 32 samples to 60 seconds of audio.");
 {const ScopedLock lock(metadata);if(waveAssets.size()>=32)return Result::fail("Import limit reached for this instance; reopen it to release old tables.");}
 cycleLength=cycleLength==0?0:cycleLength==512?512:cycleLength==1024?1024:2048;const int samples=cycleLength==0?int(reader->lengthInSamples):int(std::min<int64>(reader->lengthInSamples,64*cycleLength)),frames=cycleLength==0?1:std::max(1,samples/cycleLength);AudioBuffer<float> input(int(std::min<unsigned>(reader->numChannels,2)),samples);if(!reader->read(&input,0,samples,0,true,true))return Result::fail("Could not read WAV samples.");
 auto data=std::make_unique<Imported>();data->frames=frames;data->name=file.getFileNameWithoutExtension();data->raw.resize(size_t(frames*2048));
 for(int f=0;f<frames;++f)for(int n=0;n<2048;++n){int length=cycleLength==0?samples:std::min(samples,cycleLength);float at=float(f*length)+float(n)*float(length)/2048;int a=std::min(samples-1,int(at)),b=f*length+(a-f*length+1)%length;float value=0;for(int c=0;c<input.getNumChannels();++c)value+=(input.getSample(c,a)+(input.getSample(c,b)-input.getSample(c,a))*(at-float(a)))/float(input.getNumChannels());data->raw[size_t(f*2048+n)]=SynthB::bounded(std::isfinite(value)?value:0.f,-4.f,4.f);}
 data->table=SynthB::WaveSet::fromFrames(data->raw,frames,data->name.toStdString());const auto* pointer=data.get();{const ScopedLock lock(metadata);waveAssets.push_back(std::move(data));currentWave.store(pointer,std::memory_order_release);}write(SynthB::Schema::get().loc.osc[size_t(SynthB::bounded(oscillator,0,1))]+SynthB::table,30);return Result::ok();
}
void PrismProcessor::snapshot(){scene=patch();}
void PrismProcessor::swapScene(){auto now=patch();if(!scene.isVoid())restore(scene);scene=now;}
void PrismProcessor::route(int src,int dest){if(src<=0||src>=SynthB::modulationSourceCount||dest<0||dest>=int(SynthB::Schema::get().specs.size()))return;const auto& l=SynthB::Schema::get().loc;
 for(int n=0;n<SynthB::routes;++n){int b=l.route[n];if(int(read(b))==src&&int(read(b+1))==dest+1)return;}
 for(int n=0;n<SynthB::routes;++n){int b=l.route[n];if(read(b)<.5f){undo.beginNewTransaction("Add modulation");write(b,float(src));write(b+1,float(dest+1));write(b+2,.2f);write(b+3,1);write(b+4,1);return;}}
}
void PrismProcessor::reorder(int from,int to){if(from<0||to<0||from>=10||to>=10||from==to)return;auto& l=SynthB::Schema::get().loc;std::array<int,10> order{};for(int i=0;i<10;++i)order[size_t(i)]=int(read(l.order[i]));order=SynthB::resolvedRack(order);int moving=order[size_t(from)];if(from<to)for(int i=from;i<to;++i)order[size_t(i)]=order[size_t(i+1)];else for(int i=from;i>to;--i)order[size_t(i)]=order[size_t(i-1)];order[size_t(to)]=moving;undo.beginNewTransaction("Reorder rack");for(int i=0;i<10;++i)write(l.order[i],float(order[size_t(i)]));}
void PrismProcessor::randomize(){
 Random random;const auto& l=SynthB::Schema::get().loc;auto unlocked=[&](int section){return read(l.locks[size_t(section)])<.5f;};auto range=[&](float lo,float hi){return lo+random.nextFloat()*(hi-lo);};undo.beginNewTransaction("Surprise me");
 if(unlocked(0)){for(int o=0;o<2;++o){int b=l.osc[o];write(b+SynthB::table,float(random.nextInt(30)));write(b+SynthB::pos,range(.05f,.9f));write(b+SynthB::unison,float(1+random.nextInt(8)));write(b+SynthB::detune,range(.05f,.38f));write(b+SynthB::wtSpread,range(0,.6f));write(b+SynthB::fine,range(-10,10));write(b+SynthB::warp1,float(random.nextInt(10)));write(b+SynthB::amount1,range(0,.5f));write(b+SynthB::warp2,0);write(b+SynthB::level,o==0?.75f:range(.15f,.5f));}write(l.noise,range(0,.035f));}
 if(unlocked(1)){for(int f=0;f<2;++f){int b=l.filter[f];write(b+SynthB::type,float(random.nextInt(9)));write(b+SynthB::cutoff,std::exp(range(std::log(650.f),std::log(18000.f))));write(b+SynthB::resonance,range(.05f,.6f));write(b+SynthB::drive,range(0,.18f));write(b+SynthB::vowel,range(0,1));}write(l.routing,float(random.nextInt(3)));}
 if(unlocked(2)){for(int e=0;e<3;++e){int b=l.env[e];write(b+SynthB::attack,range(.002f,.35f));write(b+SynthB::decay,range(.12f,1.3f));write(b+SynthB::sustain,range(.15f,.9f));write(b+SynthB::release,range(.1f,1.5f));}}
 if(unlocked(3)){for(int n=0;n<SynthB::routes;++n)write(l.route[n],0);for(int o=0;o<2;++o){int b=l.route[o];write(b,4.f+float(o));write(b+1,float(l.osc[o]+SynthB::pos+1));write(b+2,range(.08f,.3f));}for(int i=0;i<4;++i)write(l.lfo[i]+SynthB::division,float(5+random.nextInt(5)));}
 if(unlocked(4)){write(l.seq+SynthB::seqOn,random.nextBool()?1.f:0.f);for(int step=0;step<16;++step){constexpr int scale[]{0,2,3,5,7,10,12};write(l.seq+SynthB::stepPitch0+step,float(scale[random.nextInt(7)]));write(l.seq+SynthB::stepGate0+step,random.nextFloat()>.15f?range(.4f,1.f):0);write(l.seq+SynthB::stepVelocity0+step,range(.5f,1));}}
 if(unlocked(5)){for(int f=0;f<10;++f){write(l.fx[f],f==3||f==4||f==6||f==9||random.nextFloat()>.6f?1.f:0.f);write(l.fx[f]+SynthB::fxMix,f==6?1.f:range(.08f,.35f));}write(l.space,range(.08f,.45f));write(l.euphoria,range(.05f,.55f));}
 {const ScopedLock lock(metadata);patchTitle="New spectrum "+String(random.nextInt(9999));category="Generated";tags={"generated","modern"};}
}
